import re
import json
import os
def task_func(file_path: str, regex_pattern=r'\(.+?\)|\w') -> dict:
    with open(file_path, 'r') as f:
        data = json.load(f)
    if isinstance(data, str):
        matches = re.findall(regex_pattern, data)
    elif isinstance(data, list):
        matches = []
        for item in data:
            matches.extend(re.findall(regex_pattern, str(item)))
    else:
        matches = re.findall(regex_pattern, str(data))
    filename = os.path.basename(file_path)
    return {filename: matches}

