import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)

    def process(obj):
        if isinstance(obj, dict):
            return {k: process(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [process(item) for item in obj]
        elif obj is None:
            return REPLACE_NONE
        elif isinstance(obj, str) and re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', obj):
            return REPLACE_NONE
        else:
            return obj

    processed = process(data)

    def flatten(obj):
        values = []
        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(flatten(v))
        elif isinstance(obj, list):
            for item in obj:
                values.extend(flatten(item))
        else:
            values.append(obj)
        return values

    flat_values = flatten(processed)
    value_counts = Counter(flat_values)

    return {"data": processed, "value_counts": value_counts}

